    TMEMBER INTEGER,
    TPROJ   INTEGER,
    FOREIGN KEY (TMEMBER) REFERENCES PAYROLL(EMPL)
);

counterexample:
-- No counterexample exists as the queries are equivalent
-- Both queries return the same result for all possible data
INSERT INTO R (X) VALUES (1);
INSERT INTO R (X) VALUES (2);
INSERT INTO R (X) VALUES (1);
-- Both Q1 and Q2 will return: {1, 2}

q2:
SELECT DISTINCT *
FROM (
  SELECT * FROM R AS X WHERE X.X > 50
  UNION ALL
  SELECT * FROM R AS Y WHERE Y.X < 200
) AS T;

SELECT * FROM R1 AS X, R2 AS Y
UNION ALL
SELECT * FROM R1 AS X, R3 AS Y;

